import React, { useState } from "react";
import axios from "axios";
import "./App.css";

function App() {
  const [resume, setResume] = useState("");
  const [jd, setJd] = useState("");
  const [output, setOutput] = useState("");
  const [score, setScore] = useState("");
  const [loading, setLoading] = useState(false);

  // ================= OPTIMIZE =================
  const handleSubmit = async () => {
    try {
      setLoading(true);

      const res = await axios.post(
        "http://localhost:5000/api/resume/optimize",
        {
          resumeText: resume,
          jobDesc: jd,
        }
      );

      setOutput(res.data.data);
      setScore(res.data.atsScore);
    } catch (err) {
      console.error(err);
      alert("Error optimizing resume");
    } finally {
      setLoading(false);
    }
  };

  // ================= DOWNLOAD PDF =================
  const handleDownload = async () => {
    try {
      const res = await axios.post(
        "http://localhost:5000/api/resume/download",
        {
          optimized: output, // ✅ FIXED HERE
        },
        {
          responseType: "blob",
        }
      );

      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement("a");

      link.href = url;
      link.setAttribute("download", "resume.pdf");

      document.body.appendChild(link);
      link.click();
    } catch (err) {
      console.error(err);
      alert("PDF download failed");
    }
  };

  return (
    <div className="container">
      <h1>CareerForge Pro 🚀</h1>

      {/* RESUME INPUT */}
      <textarea
        placeholder="Paste Resume"
        value={resume}
        onChange={(e) => setResume(e.target.value)}
      />

      {/* JOB DESCRIPTION */}
      <textarea
        placeholder="Paste Job Description"
        value={jd}
        onChange={(e) => setJd(e.target.value)}
      />

      {/* BUTTON */}
      <button onClick={handleSubmit} disabled={loading}>
        {loading ? "Optimizing..." : "Optimize Resume"}
      </button>

      {/* OUTPUT */}
      {output && (
        <div className="output">
          <h3>ATS Score: {score}%</h3>
          <h2>Optimized Resume</h2>

          <pre style={{ whiteSpace: "pre-wrap" }}>{output}</pre>

          {/* COPY BUTTON */}
          <button onClick={() => navigator.clipboard.writeText(output)}>
            Copy Resume
          </button>

          {/* DOWNLOAD BUTTON */}
          <button onClick={handleDownload}>
            Download PDF
          </button>
        </div>
      )}
    </div>
  );
}

export default App;
